label("$a$",(3.3,0.38),NE);
label("$2a$",(1.4,0.38),N);
label("2",(2,0),S);
label("1",(A + B)/2,NW);
label("$A$",A,SW);
label("$C$",C,SE);
label("$B$",B,N);
label("$M$",(B+ C)/2,NE);
